package org.opentaint.dataflow.ap.ifds

import org.opentaint.ir.api.common.CommonMethod
import org.opentaint.ir.api.common.cfg.CommonInst

interface MethodContext

data object EmptyMethodContext : MethodContext {
    override fun toString(): String = "{}"
}

data class CombinedMethodContext(val first: MethodContext, val second: MethodContext) : MethodContext {
    override fun toString() = "$first & $second"
}

fun Set<MethodContext>.combine(): MethodContext = reduce { acc, context ->
    if (context is EmptyMethodContext) return@reduce acc
    if (acc is EmptyMethodContext) return@reduce context
    CombinedMethodContext(acc, context)
}

data class MethodWithContext(val method: CommonMethod, val ctx: MethodContext)

data class MethodEntryPoint(val context: MethodContext, val statement: CommonInst) {
    val method: CommonMethod get() = statement.location.method

    override fun toString(): String = "$method [$context]"
}

JoinedStaticGuidance.kt.text:
package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.FrozenCompletion
import org.opentaint.dataflow.bidi.store.FrozenStaticCompletion
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.OwnedScope
import org.opentaint.dataflow.bidi.store.ScopedSummaryKey
import org.opentaint.dataflow.graph.PortId
import kotlin.time.Duration
import kotlin.time.TimeSource

internal data class JoinedStaticGuidance(
    val completion: FrozenCompletion,
    val binding: JoinedStaticWriterBinding.Statistics,
    val observedCandidates: Long,
    val lostCandidates: Long,
    val peakCandidates: Long,
    val pruneTime: Duration,
    val writerTime: Duration,
    val closureFreezeTime: Duration,
)

/** Runs after successful runner join and before actor/subscription release.
 * Its only exports are immutable guidance and aggregate counters. */
internal fun completeJoinedStaticGuidance(
    config: RunConfig,
    shared: SharedObjects,
    actors: List<RunMethodAnalyzer>,
    storage: (MethodKey) -> SummaryStorage?,
    checkpoint: () -> Unit,
): JoinedStaticGuidance {
    val byMethod = actors.associateBy { it.key }
    return completeFromSources(config, shared, actors.flatMap { it.detachJoinedStaticSources() },
        borrow = { owner, writer, visit ->
            if (owner.local == BlockScope.ROOT) storage(owner.method)?.visitJoinedInputs(writer, config.mode) {
                check(it.callee == owner.method)
                visit(OwnedWriterInput.call(it))
            } else byMethod[owner.method]?.forEachJoinedLocalInput(owner.local) { link, actual ->
                checkpoint(); check(link.child == owner.local)
                visit(OwnedWriterInput.local(owner.method, link, actual))
            }
        }, checkpoint = checkpoint)
}

internal fun completeJoinedStaticGuidance(
    config: RunConfig,
    shared: SharedObjects,
    sources: List<JoinedStaticSource>,
    inputs: JoinedBindingLease,
    checkpoint: () -> Unit,
): JoinedStaticGuidance = completeFromSources(config, shared, sources,
    borrow = { owner, writer, visit ->
        if (owner.local == BlockScope.ROOT) inputs.visitCallerInputs(owner.method, writer, config.mode) {
            check(it.callee == owner.method)
            visit(OwnedWriterInput.call(it))
        } else inputs.visitLocalInputs(owner) { link, actual ->
            checkpoint(); check(link.child == owner.local)
            visit(OwnedWriterInput.local(owner.method, link, actual))
        }
    }, checkpoint = checkpoint)

private fun completeFromSources(
    config: RunConfig,
    shared: SharedObjects,
    sources: List<JoinedStaticSource>,
    borrow: (OwnedScope, Publication, (OwnedWriterInput) -> Unit) -> Unit,
    checkpoint: () -> Unit,
): JoinedStaticGuidance {
    check(config.run1)
    val builder = FrozenStaticCompletion.Builder(shared.ap, shared.staticCallGraph)
    val keys = shared.staticWriteKeyInterner
    fun seed(owner: OwnedScope, original: Pattern, output: Pattern, exit: PortId = PortId.STATIC_SHORTCUT) {
        if (owner.local == BlockScope.ROOT) builder.addSeed(owner.method, original, output)
        else builder.addScopedSeed(ScopedSummaryKey(owner.method, owner.local, exit), original, output)
    }
    val binding = OwnedJoinedStaticWriterBinding(shared.ops, config.mode, keys,
        borrow = borrow,
        onBound = { owner, original, output -> seed(owner, original.toPattern(), output) },
        checkpoint = checkpoint)
    var observed = 0L
    var lost = 0L
    var peak = 0L
    var pruneTime = Duration.ZERO
    for (source in sources) {
        checkpoint()
        val owner = source.owner
        val scope = owner.local
        val shortcut = ScopedSummaryKey(owner.method, scope, PortId.STATIC_SHORTCUT)
        if (scope != BlockScope.ROOT) builder.addScopedBoundary(shortcut)
        val pruneStarted = TimeSource.Monotonic.markNow()
        val writes = source.freezeWrites()
        pruneTime += pruneStarted.elapsedNow()
        observed += writes.observedCount
        lost += writes.lostCount
        peak += writes.peakCount
        writes.forEachLostId { id ->
            checkpoint()
            val row = keys.row(id)
            seed(owner, row.original.toPattern(), row.result)
        }
        // Primitive writers bind through their own local parents before the root's real callers.
        // No static-composed closure result enters this queue.
        writes.forEachObservedId { id ->
            checkpoint()
            if (keys.row(id).original.base != STATIC) binding.offer(owner, id)
        }
        for (bridge in source.privateSeeds.frozenRows()) {
            checkpoint()
            seed(owner, bridge.from, bridge.to)
        }
        for (terminal in source.outgoingDemandTargets) {
            checkpoint()
            check(terminal.target == Target.DemandTarget)
            val original = checkNotNull(terminal.premise as? InitialAp) { "Run-1 cannot retain an ND original" }
            if (scope == BlockScope.ROOT) builder.addTarget(owner.method, original.toPattern())
            else builder.addScopedTarget(ScopedSummaryKey(owner.method, scope, PortId.ROOT_EXIT), original.toPattern())
        }
        val stores = source.exitStores()
        for ((exit, summaries) in stores) {
            if (scope != BlockScope.ROOT) builder.addScopedBoundary(ScopedSummaryKey(owner.method, scope, exit))
            for ((original, facts) in summaries.demandEdges(Direction.FORWARD)) {
                checkpoint()
                check(original is InitialAp) { "Run-1 cannot retain an ND original" }
                for (piece in shared.ops.leaves(facts)) {
                    checkpoint()
                    seed(owner, original.toPattern(), piece, exit)
                    if (piece.fact.base == STATIC && original.base != STATIC)
                        binding.offer(owner, keys.intern(original, piece))
                }
            }
        }
    }
    val writerStarted = TimeSource.Monotonic.markNow()
    val counters = binding.complete()
    val writerTime = writerStarted.elapsedNow()
    checkpoint()
    val freezeStarted = TimeSource.Monotonic.markNow()
    val frozen = builder.build()
    val freezeTime = freezeStarted.elapsedNow()
    checkpoint()
    return JoinedStaticGuidance(frozen, counters, observed, lost, peak, pruneTime, writerTime, freezeTime)
}

OwnedJoinedStaticWriterBinding.kt.text:
package org.opentaint.dataflow.bidi.engine

import it.unimi.dsi.fastutil.ints.IntOpenHashSet
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.CallerRef
import org.opentaint.dataflow.bidi.store.OwnedScope
import org.opentaint.dataflow.bidi.store.StaticWriteKeyInterner

/** Only an existing live input link can bind a primitive writer. */
internal sealed interface OwnedWriterInputKey {
    data class Local(val link: LocalLink) : OwnedWriterInputKey
    data class Call(val ref: CallerRef, val zeroOnly: Boolean) : OwnedWriterInputKey
}

internal class OwnedWriterInput private constructor(
    val parent: OwnedScope,
    val original: InitialAp,
    val actual: Facts,
    val key: OwnedWriterInputKey,
    val zeroOnly: Boolean,
) {
    companion object {
        fun local(method: MethodKey, link: LocalLink, actual: Facts): OwnedWriterInput =
            OwnedWriterInput(OwnedScope(method, link.parent),
                checkNotNull(link.original as? InitialAp) { "Run-1 local originals are singleton" }, actual,
                OwnedWriterInputKey.Local(link), zeroOnly = false)

        fun call(part: Subscription): OwnedWriterInput =
            OwnedWriterInput(OwnedScope(part.ref.caller, part.ref.scope),
                checkNotNull(part.ref.premise as? InitialAp) { "Run-1 caller originals are singleton" }, part.added,
                OwnedWriterInputKey.Call(part.ref, part.zeroOnly), part.zeroOnly)
    }
}

/** Joined phase A. Bind local inputs first, then real method callers at the root.
 *
 * It borrows existing current inputs after all runners join. No second standing input store,
 * synthetic method, alias application, static composition or new request authority is added.
 */
internal class OwnedJoinedStaticWriterBinding(
    private val ops: ApOps,
    private val mode: ApMode,
    private val keys: StaticWriteKeyInterner,
    private val borrow: (OwnedScope, Publication, (OwnedWriterInput) -> Unit) -> Unit,
    private val onBound: (OwnedScope, InitialAp, Pattern) -> Unit,
    private val checkpoint: () -> Unit,
) {
    private data class Writer(val owner: OwnedScope, val id: Int)
    private data class InputKey(val key: OwnedWriterInputKey, val group: GroupKey)
    private val admitted = HashMap<OwnedScope, IntOpenHashSet>()
    private val pending = ArrayDeque<Writer>()
    private var offers = 0L
    private var processed = 0L
    private var candidates = 0L
    private var matchedInputs = 0L
    private var duplicateInputs = 0L
    private var outputs = 0L

    init { check(mode.run1) }

    fun offer(owner: OwnedScope, id: Int) {
        checkpoint()
        val row = keys.row(id)
        if (!RuntimeDataDomain.initial(row.original) || !RuntimeDataDomain.base(row.result.fact.base)) return
        check(row.result.fact.base == STATIC)
        check(row.original.base != STATIC) { "Static originals enter the frozen bridge graph, never writer binding" }
        offers++
        if (admitted.getOrPut(owner, ::IntOpenHashSet).add(id)) pending += Writer(owner, id)
    }

    fun complete(): JoinedStaticWriterBinding.Statistics {
        val ap = ops.manager
        while (pending.isNotEmpty()) {
            checkpoint()
            val writer = pending.removeFirst()
            val row = keys.row(writer.id)
            val conclusion = ap.factsOf(row.result.fact, row.result.exclusion, Layer.DEMAND)
            val publication = Publication(row.original, conclusion)
            val visited = HashSet<InputKey>()
            processed++
            borrow(writer.owner, publication) { input ->
                checkpoint()
                if (!RuntimeDataDomain.packet(input.original, input.actual)) return@borrow
                check((input.actual is FlowTree) == input.original.isFlow)
                candidates++
                if (!visited.add(InputKey(input.key, input.actual.groupKey))) {
                    duplicateInputs++
                    return@borrow
                }
                // Do not turn an arbitrary reached ZERO packet into a new source authority.
                if (row.original.isZero && (!input.original.isZero || input.actual !is Reach)) return@borrow
                val actual = if (input.zeroOnly) input.actual.takeIf { row.original.isZero }
                    else ops.satisfying(input.actual, row.original, mode)
                if (actual == null) return@borrow
                matchedInputs++
                val out = object : ApOut {
                    override fun result(f: Facts) {
                        checkpoint()
                        check(f.base == STATIC)
                        // This is the existing static-result lane. Keep raw mx until AP
                        // application ends; no configured call suffix or aliases execute.
                        ops.run1Cover(f.withLayer(Layer.DEMAND)) { covered ->
                            ops.limit(covered, mode.fieldLimit, object : ApOut {
                                override fun result(f: Facts) {
                                    ops.run1Cover(f.withLayer(Layer.DEMAND)) { bounded ->
                                        for (piece in ops.leaves(bounded)) {
                                            checkpoint()
                                            outputs++
                                            onBound(input.parent, input.original, piece)
                                            if (input.original.base != STATIC)
                                                offer(input.parent, keys.intern(input.original, piece))
                                        }
                                    }
                                }
                                override fun markRequest(mark: TaintMark) =
                                    error("A joined field cut cannot create a mark request")
                            })
                        }
                    }
                    // Live execution already owns the exclusion's request.
                    override fun markRequest(mark: TaintMark) = Unit
                }
                if (input.zeroOnly) out.result(conclusion)
                else ops.applySummary(actual, row.original, conclusion, mode, out, original = input.original)
            }
        }
        checkpoint()
        return JoinedStaticWriterBinding.Statistics(offers, admitted.values.sumOf { it.size.toLong() }, processed,
            candidates, duplicateInputs, matchedInputs, outputs)
    }
}

Trie.kt.text:
package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import java.util.ArrayDeque
import java.util.IdentityHashMap
import java.util.concurrent.ConcurrentHashMap

interface TrieLeaf {
    val isEmpty: Boolean
    val hasAny: Boolean
}

enum class FlowLeaf : TrieLeaf {
    NONE, LEAF;
    override val isEmpty: Boolean get() = this == NONE
    override val hasAny: Boolean get() = false
}

class TaintLeaves internal constructor(val exact: MarkSet, val any: MarkSet) : TrieLeaf {
    private val hash = exact.hashCode() * 31 + any.hashCode()
    override val isEmpty: Boolean get() = exact.isEmpty && any.isEmpty
    override val hasAny: Boolean get() = !any.isEmpty
    override fun equals(other: Any?): Boolean = this === other ||
        (other is TaintLeaves && hash == other.hash && exact == other.exact && any == other.any)
    override fun hashCode(): Int = hash
    companion object { @JvmField val EMPTY = TaintLeaves(MarkSet.EMPTY, MarkSet.EMPTY) }
}

/** Immutable sorted children. Public arrays are snapshots of the owned content. */
class TrieNode<P : TrieLeaf> internal constructor(
    @JvmField val leaf: P,
    accessors: IntArray?,
    children: Array<TrieNode<P>>?,
    @JvmField val interned: Boolean,
) {
    internal val accessorData: IntArray? = accessors?.takeIf { it.isNotEmpty() }?.copyOf()
    internal val childData: Array<TrieNode<P>>? = children?.takeIf { it.isNotEmpty() }?.copyOf()
    val accessors: IntArray? get() = accessorData?.copyOf()
    val children: Array<TrieNode<P>>? get() = childData?.copyOf()
    @JvmField val hash: Long
    @JvmField val boundedDepth: Int
    @JvmField val hasAny: Boolean
    @JvmField val size: Long
    @JvmField internal var allLeaves: P? = null

    init {
        check((accessorData == null) == (childData == null)) { "Child arrays must be aligned" }
        check(accessorData == null || accessorData.size == childData!!.size) { "Child arrays must have equal sizes" }
        var h = leaf.hashCode().toLong()
        var depth = 0
        var any = leaf.hasAny
        var count = 1L
        if (accessorData != null) for (i in accessorData.indices) {
            val accessor = accessorData[i]
            check(accessor.isPathAccessor()) { "W5: a trie edge needs a path accessor" }
            check(i == 0 || accessorData[i - 1] < accessor) { "Trie accessors must be sorted and unique" }
            val child = childData!![i]
            check(!child.isEmpty) { "A child subtree must be nonempty" }
            count = Math.addExact(count, child.size)
            h += (child.hash * 31 + accessor) shl 5
            depth = maxOf(depth, Math.addExact(child.boundedDepth, if (accessor.isCounted()) 1 else 0))
            any = any || child.hasAny
        }
        hash = h
        boundedDepth = depth
        hasAny = any
        size = count
    }

    val isEmpty: Boolean get() = leaf.isEmpty && accessorData == null
    fun child(accessor: AccessorIdx): TrieNode<P>? {
        val index = accessorData?.binarySearch(accessor) ?: return null
        return if (index < 0) null else childData!![index]
    }

    override fun hashCode(): Int = hash.toInt()

    /** Shared DAGs and deep paths compare by value without recursive calls. */
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is TrieNode<*>) return false
        val pending = ArrayDeque<Pair<TrieNode<*>, TrieNode<*>>>()
        val seen = IdentityHashMap<TrieNode<*>, IdentityHashMap<TrieNode<*>, Boolean>>()
        pending.addLast(this to other)
        while (pending.isNotEmpty()) {
            val (a, b) = pending.removeLast()
            if (a === b) continue
            if (a.hash != b.hash || a.size != b.size || a.boundedDepth != b.boundedDepth ||
                a.hasAny != b.hasAny || a.leaf != b.leaf || !a.accessorData.contentEquals(b.accessorData)) return false
            if (seen.getOrPut(a) { IdentityHashMap() }.put(b, true) != null) continue
            val x = a.childData
            val y = b.childData
            if (x == null || y == null) {
                if (x !== y) return false
                continue
            }
            if (x.size != y.size) return false
            for (i in x.indices) pending.addLast(x[i] to y[i])
        }
        return true
    }
}

typealias FlowNode = TrieNode<FlowLeaf>
typealias TaintNode = TrieNode<TaintLeaves>

abstract class LeafAlgebra<P : TrieLeaf> {
    abstract val empty: P
    abstract fun union(a: P, b: P): P
    abstract fun minus(a: P, b: P): P
    abstract fun below(p: P): P
    abstract fun asAny(p: P): P
    abstract fun intern(p: P): P
    private val leafNodes = ConcurrentHashMap<P, TrieNode<P>>()

    fun leafNode(p: P): TrieNode<P> = leafNodes.computeIfAbsent(intern(p)) { TrieNode(it, null, null, true) }

    fun node(p: P, accessors: IntArray?, children: Array<TrieNode<P>>?): TrieNode<P> {
        val a = accessors?.takeIf { it.isNotEmpty() }
        val c = children?.takeIf { it.isNotEmpty() }
        check((a == null) == (c == null)) { "Child arrays must be aligned" }
        return if (a == null) leafNode(p) else TrieNode(intern(p), a, c, false)
    }
}

object FlowAlgebra : LeafAlgebra<FlowLeaf>() {
    override val empty: FlowLeaf get() = FlowLeaf.NONE
    override fun union(a: FlowLeaf, b: FlowLeaf) = if (!a.isEmpty || !b.isEmpty) FlowLeaf.LEAF else FlowLeaf.NONE
    override fun minus(a: FlowLeaf, b: FlowLeaf) = if (!a.isEmpty && b.isEmpty) FlowLeaf.LEAF else FlowLeaf.NONE
    override fun below(p: FlowLeaf) = p
    override fun asAny(p: FlowLeaf) = p
    override fun intern(p: FlowLeaf) = p
    val LEAF_NODE: FlowNode get() = leafNode(FlowLeaf.LEAF)
}

class TaintAlgebra(private val m: ApManager) : LeafAlgebra<TaintLeaves>() {
    private val table = ConcurrentHashMap<TaintLeaves, TaintLeaves>()
    override val empty: TaintLeaves get() = TaintLeaves.EMPTY
    fun leaves(exact: MarkSet, any: MarkSet): TaintLeaves = intern(TaintLeaves(m.intern(exact), m.intern(any)))
    override fun intern(p: TaintLeaves): TaintLeaves =
        if (p.isEmpty) TaintLeaves.EMPTY else table.putIfAbsent(p, p) ?: p
    override fun union(a: TaintLeaves, b: TaintLeaves): TaintLeaves =
        if (a === b) a else leaves(a.exact + b.exact, a.any + b.any)
    override fun minus(a: TaintLeaves, b: TaintLeaves) = leaves(a.exact - b.exact, a.any - b.any)
    override fun below(p: TaintLeaves) = leaves(p.any, p.any)
    fun belowNormal(p: TaintLeaves) = leaves(MarkSet.EMPTY, p.any)
    fun belowIn(layer: Layer): (TaintLeaves) -> TaintLeaves = if (layer == Layer.NORMAL) this::belowNormal else this::below
    override fun asAny(p: TaintLeaves) = leaves(MarkSet.EMPTY, p.exact + p.any)
}

Premise.kt.text:
package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.MethodEntryPoint

typealias MethodKey = MethodEntryPoint

sealed interface PremiseKey {
    val size: Int
    fun member(k: Int): InitialAp
    val isZero: Boolean
    val nonZeroCount: Int
}

val PremiseKey.members: List<InitialAp> get() = List(size, ::member)
inline fun PremiseKey.forEachMember(body: (InitialAp) -> Unit) {
    for (index in 0 until size) body(member(index))
}
val PremiseKey.isFlow: Boolean get() = this is InitialAp && mark is MarkSlot.Star

/** Equality is identity after interning. Mode-specific must checks belong to the run. */
class InitialAp internal constructor(
    val base: AccessPathBase,
    val path: PathNode?,
    val tail: Tail,
    val exclusion: ExclusionSet,
    val mark: MarkSlot,
    @JvmField val id: Int,
    @JvmField internal val manager: ApManager,
) : PremiseKey {
    init {
        check(base !is AccessPathBase.CleanerTemporary) { "A field-action temporary cannot be a premise" }
        check(mark !is MarkSlot.Star || mark.excluded.isEmpty) { "A premise cannot exclude marks" }
        check(tail == Tail.STAR || tail == Tail.ANY_TAINT || exclusion == ExclusionSet.Empty) {
            "Only a STAR or must premise can exclude fields"
        }
        check(base != AccessPathBase.Zero || (path == null && tail == Tail.EXACT &&
            exclusion == ExclusionSet.Empty && mark == MarkSlot.Concrete(TaintMark.ZERO))) {
            "The zero base has only the canonical zero fact"
        }
    }

    internal val pathData: IntArray = path?.toIntArray() ?: EMPTY_PATH
    val pathArray: IntArray get() = pathData.copyOf()
    override val size: Int get() = 1
    override fun member(k: Int): InitialAp = also { check(k == 0) }
    override val isZero: Boolean get() = base == AccessPathBase.Zero
    override val nonZeroCount: Int get() = if (isZero) 0 else 1
    fun toPattern(): Pattern = Pattern(PathFact(base, pathArray.asList(), tail, mark), exclusion)
}

class PremiseSet internal constructor(members: Array<InitialAp>) : PremiseKey {
    private val data = members.copyOf()
    val members: Array<InitialAp> get() = data.copyOf()

    init {
        check(data.size >= 2)
        check(data.none { it.isZero }) { "A multiple-member premise cannot include zero" }
        check(data.all { it.mark is MarkSlot.Concrete }) { "Every multiple-member premise must be concrete" }
        check((1 until data.size).all { data[it - 1].id < data[it].id }) {
            "Premise members must be sorted and unique"
        }
    }

    override val size: Int get() = data.size
    override fun member(k: Int): InitialAp = data[k]
    override val isZero: Boolean get() = false
    override val nonZeroCount: Int get() = data.size
}

JoinedBindingLease.kt.text:
package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.graph.PortId
import java.util.IdentityHashMap

internal enum class JoinedPreparationPhase { CAPTURED, SEALED, RELEASED, BEFORE_BIND, BOUND, CLOSED }

/** Plain stopped-owner values. No actor, runtime, runner or callback is captured. */
internal class JoinedStaticSource(
    val owner: OwnedScope,
    private val root: RunSummaryStore?,
    private val ports: PortSummaryStores?,
    val outgoingDemandTargets: Set<TargetSummary>,
    val privateSeeds: StaticGuidanceSeedStore,
    private val rawWrites: KilledStaticWriteStore,
) {
    fun exitStores(): Sequence<Pair<PortId, RunSummaryStore>> =
        root?.let { sequenceOf(PortId.ROOT_EXIT to it) } ?: checkNotNull(ports).entries()
    fun freezeWrites(): FrozenStaticWrites = rawWrites.freeze(
        exitStores().flatMap { it.second.all() }, privateSeeds.frozenRows())
}

/** Joined-only directories. Every map entry keeps its original complete owner key. */
internal class JoinedBindingLease : AutoCloseable {
    private val local = LinkedHashMap<OwnedScope, JoinedLocalInputs>()
    private val callerOwners = IdentityHashMap<SubscriptionManager, JoinedCallerInputs>()
    private val callers = LinkedHashMap<MethodKey, List<JoinedCallerInputs>>()
    private var closed = false

    fun addLocal(method: MethodKey, inputs: Map<BlockScope, JoinedLocalInputs>) {
        check(!closed)
        try {
            for ((scope, reader) in inputs) {
                val owner = OwnedScope(method, scope)
                check(owner !in local) { "Joined local owner was already captured" }
                local[owner] = reader
            }
        } catch (error: Throwable) {
            // The lease retains registered owners; close every reader it failed to adopt.
            for ((scope, reader) in inputs) if (local[OwnedScope(method, scope)] !== reader) try {
                reader.close()
            } catch (closeError: Throwable) { if (closeError !== error) error.addSuppressed(closeError) }
            throw error
        }
    }
    fun addCallers(storage: SummaryStorage) {
        check(!closed)
        callers[storage.method] = storage.detachJoinedSubscribers { subscriber ->
            callerOwners[subscriber] ?: subscriber.detachJoinedInputs().also { reader ->
                try { callerOwners[subscriber] = reader } catch (error: Throwable) {
                    try { reader.close() } catch (closeError: Throwable) {
                        if (closeError !== error) error.addSuppressed(closeError)
                    }
                    throw error
                }
            }
        }
    }
    fun visitLocalInputs(owner: OwnedScope, visit: (LocalLink, Facts) -> Unit) {
        check(!closed) { "Joined binding lease is closed" }
        local[owner]?.visit(visit)
    }
    fun visitCallerInputs(method: MethodKey, writer: Publication, mode: ApMode, visit: (Subscription) -> Unit) {
        check(!closed) { "Joined binding lease is closed" }
        for (reader in callers[method].orEmpty()) reader.visit(method, writer, mode, visit)
    }
    override fun close() {
        if (closed) return
        closed = true
        var failure: Throwable? = null
        fun close(action: () -> Unit) {
            try { action() } catch (error: Throwable) {
                val first = failure
                if (first == null) failure = error else if (first !== error) first.addSuppressed(error)
            }
        }
        for (reader in local.values) close { reader.close() }
        for (reader in callerOwners.values) close { reader.close() }
        local.clear(); callers.clear(); callerOwners.clear()
        failure?.let { throw it }
    }
}

