package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

enum class Direction { FORWARD, BACKWARD }
enum class Layer { NORMAL, DEMAND }
enum class Tail { STAR, ANY, ANY_TAINT, EXACT }

val Tail.isAny: Boolean get() = this == Tail.ANY || this == Tail.ANY_TAINT
infix fun Layer.or(demand: Boolean): Layer = if (demand) Layer.DEMAND else this

/** Run 1 is forward. Every run has a positive field limit. */
class ApMode(val run1: Boolean, val direction: Direction, val fieldLimit: Int,
             val markMode: MarkMode = MarkMode.FULL) {
    val restricted: Boolean get() = !run1

    init {
        require(fieldLimit >= 1) { "The field limit must be positive" }
        require(!run1 || direction == Direction.FORWARD) { "Run 1 must be forward" }
    }
}

@JvmInline
value class TaintMark(val id: Int) {
    companion object { val ZERO = TaintMark(0) }
}

/** A canonical immutable set. Public arrays are snapshots of the owned content. */
class MarkSet(ids: IntArray) {
    internal val data: IntArray = ids.sortedDistinct()
    val ids: IntArray get() = data.copyOf()
    private val hash = data.contentHashCode()
    val isEmpty: Boolean get() = data.isEmpty()
    val size: Int get() = data.size

    operator fun contains(mark: TaintMark): Boolean = data.binarySearch(mark.id) >= 0
    fun isSubsetOf(other: MarkSet): Boolean = this === other || sortedSubset(data, other.data)
    operator fun plus(other: MarkSet): MarkSet =
        if (other.isSubsetOf(this)) this else MarkSet(sortedUnion(data, other.data))
    operator fun plus(mark: TaintMark): MarkSet =
        if (mark in this) this else MarkSet(sortedUnion(data, intArrayOf(mark.id)))
    operator fun minus(other: MarkSet): MarkSet =
        MarkSet(data.filter { other.data.binarySearch(it) < 0 }.toIntArray())
    infix fun intersect(other: MarkSet): MarkSet =
        MarkSet(data.filter { other.data.binarySearch(it) >= 0 }.toIntArray())
    fun forEach(visit: (TaintMark) -> Unit) { data.forEach { visit(TaintMark(it)) } }

    override fun equals(other: Any?): Boolean = this === other ||
        (other is MarkSet && hash == other.hash && data.contentEquals(other.data))
    override fun hashCode(): Int = hash
    override fun toString(): String = data.joinToString(prefix = "{", postfix = "}")

    companion object {
        val EMPTY = MarkSet(IntArray(0))
        fun of(mark: TaintMark): MarkSet = MarkSet(intArrayOf(mark.id))
    }
}

sealed interface MarkSlot {
    data class Star(val excluded: MarkExclusions) : MarkSlot {
        constructor(excluded: MarkSet) : this(MarkExclusions.fromMarks(excluded))
    }
    data class Concrete(val mark: TaintMark) : MarkSlot
    companion object { val STAR = Star(MarkSet.EMPTY) }
}

/** Only the first accessor of a nonempty continuation is tested against E. */
sealed interface ExclusionSet {
    fun admits(first: AccessorIdx): Boolean
    fun admits(rest: List<AccessorIdx>): Boolean = rest.isEmpty() || admits(rest[0])
    fun union(other: ExclusionSet): ExclusionSet
    fun intersect(other: ExclusionSet): ExclusionSet
    fun isSubsetOf(other: ExclusionSet): Boolean

    data object Empty : ExclusionSet {
        override fun admits(first: AccessorIdx): Boolean = true
        override fun union(other: ExclusionSet): ExclusionSet = other
        override fun intersect(other: ExclusionSet): ExclusionSet = this
        override fun isSubsetOf(other: ExclusionSet): Boolean = true
    }

    class Concrete internal constructor(ids: IntArray) : ExclusionSet {
        internal val data: IntArray = ids.sortedDistinct()
        val ids: IntArray get() = data.copyOf()
        private val hash = data.contentHashCode()

        init { check(data.isNotEmpty()) { "A concrete exclusion must be nonempty" } }

        override fun admits(first: AccessorIdx): Boolean = data.binarySearch(first) < 0
        override fun union(other: ExclusionSet): ExclusionSet =
            if (other is Concrete) of(sortedUnion(data, other.data)) else this
        override fun intersect(other: ExclusionSet): ExclusionSet =
            if (other is Concrete) of(data.filter { other.data.binarySearch(it) >= 0 }.toIntArray()) else Empty
        override fun isSubsetOf(other: ExclusionSet): Boolean =
            other is Concrete && sortedSubset(data, other.data)
        override fun equals(other: Any?): Boolean = this === other ||
            (other is Concrete && hash == other.hash && data.contentEquals(other.data))
        override fun hashCode(): Int = hash
        override fun toString(): String = data.joinToString(prefix = "{", postfix = "}")
    }

    companion object {
        fun of(ids: IntArray): ExclusionSet = if (ids.isEmpty()) Empty else Concrete(ids)
        fun of(accessor: AccessorIdx): ExclusionSet = Concrete(intArrayOf(accessor))
    }
}

val EMPTY_PATH: IntArray = IntArray(0)

internal fun IntArray.sortedDistinct(): IntArray {
    if (isEmpty()) return IntArray(0)
    val result = sortedArray()
    var size = 1
    for (index in 1 until result.size) {
        if (result[index] != result[size - 1]) result[size++] = result[index]
    }
    return if (size == result.size) result else result.copyOf(size)
}

internal fun sortedUnion(a: IntArray, b: IntArray): IntArray {
    val result = IntArray(Math.addExact(a.size, b.size))
    var ai = 0
    var bi = 0
    var size = 0
    while (ai < a.size || bi < b.size) {
        val value = when {
            bi == b.size || (ai < a.size && a[ai] < b[bi]) -> a[ai++]
            ai == a.size || b[bi] < a[ai] -> b[bi++]
            else -> a[ai++].also { bi++ }
        }
        result[size++] = value
    }
    return result.copyOf(size)
}

internal fun sortedSubset(a: IntArray, b: IntArray): Boolean {
    var ai = 0
    var bi = 0
    while (ai < a.size && bi < b.size) {
        when {
            a[ai] == b[bi] -> { ai++; bi++ }
            a[ai] > b[bi] -> bi++
            else -> return false
        }
    }
    return ai == a.size
}

fun IntArray.startsWith(prefix: IntArray): Boolean =
    size >= prefix.size && prefix.indices.all { this[it] == prefix[it] }

MarkExclusions.kt.text:
package org.opentaint.dataflow.bidi.ap

private enum class FullAtoms { UNKNOWN, ABSENT, PRESENT }

/** FLOW restrictions denote either an entire owner group or an exact full
 * mark. The atom IDs are private representation, never raw set semantics. */
class MarkExclusions private constructor(
    private val atoms: MarkSet,
    private val catalog: MarkTable?,
    private val fullAtoms: FullAtoms,
) {
    val isEmpty: Boolean get() = atoms.isEmpty
    val ids: IntArray get() = atoms.ids
    internal val data: IntArray get() = atoms.data
    fun withCatalog(table: MarkTable): MarkExclusions {
        require(catalog == null || catalog === table) { "Mixed mark catalogs in FLOW exclusions" }
        if (catalog === table) return this
        return normalized(atoms, table)
    }
    operator fun contains(mark: TaintMark): Boolean = excludes(mark, catalog)
    private fun excludes(mark: TaintMark, table: MarkTable?): Boolean {
        if (mark in atoms) return true
        if (mark == TaintMark.ZERO || table == null || table.isGroup(mark)) return false
        return atoms.data.any { id ->
            val atom = TaintMark(id)
            table.isGroup(atom) && table.groupOf(atom) == table.groupOf(mark)
        }
    }
    operator fun plus(mark: TaintMark): MarkExclusions {
        val combined = atoms + mark
        if (combined === atoms) return this
        return normalized(combined, catalog)
    }
    operator fun plus(other: MarkExclusions): MarkExclusions = union(other)
    operator fun plus(other: MarkSet): MarkExclusions = union(fromMarks(other))
    fun union(other: MarkExclusions): MarkExclusions {
        val table = tableWith(other)
        val combined = atoms + other.atoms
        if (combined === atoms && catalog === table) return this
        return normalized(combined, table)
    }
    fun intersect(other: MarkExclusions): MarkExclusions {
        val table = tableWith(other)
        val left = atoms.data.filter { other.excludes(TaintMark(it), table) }
        val right = other.atoms.data.filter { excludes(TaintMark(it), table) }
        return normalized(MarkSet((left + right).toIntArray()), table)
    }
    fun isSubsetOf(other: MarkExclusions): Boolean {
        val table = tableWith(other)
        return atoms.data.all { id ->
            val atom = TaintMark(id)
            // A finite list of full members does not cover a group, even if
            // it happens to contain the current catalog's complete population.
            if (table?.isGroup(atom) == true) atom in other.atoms else other.excludes(atom, table)
        }
    }
    fun filterMarks(marks: MarkSet): MarkSet = MarkSet(marks.data.filter { TaintMark(it) !in this }.toIntArray())
    fun projected(table: MarkTable, mode: MarkMode): MarkExclusions {
        if (mode == MarkMode.FULL) return withCatalog(table)
        if (isEmpty) return EMPTY
        if (catalog === table && fullAtoms == FullAtoms.ABSENT) return this
        return normalized(MarkSet(atoms.data.map { table.runtimeAtom(TaintMark(it), mode).id }.toIntArray()), table)
    }
    fun forEach(visit: (TaintMark) -> Unit) = atoms.data.forEach { visit(TaintMark(it)) }
    private fun tableWith(other: MarkExclusions): MarkTable? {
        require(catalog == null || other.catalog == null || catalog === other.catalog) { "Mixed mark catalogs" }
        return catalog ?: other.catalog
    }
    override fun equals(other: Any?): Boolean = other is MarkExclusions && atoms == other.atoms
    override fun hashCode(): Int = atoms.hashCode()
    override fun toString(): String = atoms.toString()
    companion object {
        val EMPTY = MarkExclusions(MarkSet.EMPTY, null, FullAtoms.ABSENT)
        fun fromMarks(marks: MarkSet, catalog: MarkTable? = null): MarkExclusions = normalized(marks, catalog)
        fun of(catalog: MarkTable, atom: TaintMark): MarkExclusions = fromMarks(MarkSet(intArrayOf(atom.id)), catalog)
        fun of(catalog: MarkTable, atoms: Iterable<TaintMark>): MarkExclusions =
            normalized(MarkSet(atoms.map { it.id }.toIntArray()), catalog)
        private fun normalized(atoms: MarkSet, catalog: MarkTable?): MarkExclusions {
            if (atoms.isEmpty) return EMPTY
            if (catalog == null) return MarkExclusions(atoms, null, FullAtoms.UNKNOWN)
            var groups: MutableSet<GroupId>? = null
            var fullAtoms = FullAtoms.ABSENT
            for (id in atoms.data) when (val key = catalog.key(TaintMark(id))) {
                MarkAtomKey.ControlZero -> Unit
                is MarkAtomKey.Group -> {
                    val present = groups ?: HashSet<GroupId>().also { groups = it }
                    present.add(key.id)
                }
                is MarkAtomKey.Full -> fullAtoms = FullAtoms.PRESENT
            }
            val presentGroups = groups ?: return MarkExclusions(atoms, catalog, fullAtoms)
            // Metadata describes retained atoms, not the input before GROUP shadowing.
            var retainedFull = FullAtoms.ABSENT
            val kept = atoms.data.filter { id ->
                when (val key = catalog.key(TaintMark(id))) {
                    MarkAtomKey.ControlZero, is MarkAtomKey.Group -> true
                    is MarkAtomKey.Full -> (key.mark.group !in presentGroups).also {
                        if (it) retainedFull = FullAtoms.PRESENT
                    }
                }
            }
            return MarkExclusions(MarkSet(kept.toIntArray()), catalog, retainedFull)
        }
    }
}

operator fun MarkSet.minus(excluded: MarkExclusions): MarkSet = excluded.filterMarks(this)

AccessorTable.kt.text:
package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.Accessor
import org.opentaint.dataflow.ap.ifds.ClassStaticAccessor
import org.opentaint.dataflow.ap.ifds.ElementAccessor
import org.opentaint.dataflow.ap.ifds.FieldAccessor
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.BASIC_KIND_BITS
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.ELEMENT_ACCESSOR_IDX
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.FIELD_KIND
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.STATIC_KIND
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.getAccessorIdx
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.isFieldAccessor
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.isStaticAccessor
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.setAccessorKind
import java.util.concurrent.ConcurrentHashMap

/** Publish each value before its ID. Reads need one volatile array read and no retry loop. */
class AccessorTable {
    internal class Storage<T : Any> {
        private val ids = ConcurrentHashMap<T, Int>()
        @Volatile private var values: Array<Any?> = arrayOfNulls(64)
        private var size = 0

        fun index(value: T): Int = ids[value] ?: synchronized(this) {
            ids[value] ?: run {
                val index = size++
                val array = if (index < values.size) values else values.copyOf(Math.multiplyExact(2, values.size))
                array[index] = value
                values = array
                ids[value] = index
                index
            }
        }

        @Suppress("UNCHECKED_CAST")
        fun value(index: Int): T = checkNotNull(values.getOrNull(index)) { "Unknown value ID: $index" } as T
    }

    private val fields = Storage<Accessor>()
    private val statics = Storage<Accessor>()

    fun index(accessor: Accessor): AccessorIdx = when (accessor) {
        is FieldAccessor -> setAccessorKind(fields.index(accessor), FIELD_KIND, BASIC_KIND_BITS)
        is ClassStaticAccessor -> setAccessorKind(statics.index(accessor), STATIC_KIND, BASIC_KIND_BITS)
        ElementAccessor -> ELEMENT_ACCESSOR_IDX
        else -> error("W5: $accessor is not a path accessor")
    }

    fun accessor(index: AccessorIdx): Accessor = when {
        index.isFieldAccessor() -> fields.value(index.getAccessorIdx(BASIC_KIND_BITS))
        index.isStaticAccessor() -> statics.value(index.getAccessorIdx(BASIC_KIND_BITS))
        index == ELEMENT_ACCESSOR_IDX -> ElementAccessor
        else -> error("W5: $index is not a path accessor")
    }
}

fun AccessorIdx.isCounted(): Boolean = isFieldAccessor() || this == ELEMENT_ACCESSOR_IDX
fun AccessorIdx.isClass(): Boolean = isStaticAccessor()
internal fun AccessorIdx.isPathAccessor(): Boolean = this >= 0 && (isCounted() || isClass())

KilledStaticWriteStore.kt.text:
package org.opentaint.dataflow.bidi.store

import it.unimi.dsi.fastutil.ints.IntArrayList
import it.unimi.dsi.fastutil.ints.IntLinkedOpenHashSet
import it.unimi.dsi.fastutil.longs.Long2IntOpenHashMap
import it.unimi.dsi.fastutil.longs.LongArrayList
import org.opentaint.dataflow.bidi.ap.*
import java.util.Collections

/** Raw scalar data for ordinary actual-call binding. This is not an executable summary. */
data class StaticWriteKey(val original: InitialAp, val result: Pattern) {
    fun guidance(): StaticGuidanceEdge {
        val (from, to) = normalizeFlowSummaryPatterns(original.toPattern(), result)
        return StaticGuidanceEdge.of(from, to)
    }
}

private data class StaticWriteGeometry(val original: Pattern, val result: Pattern)

/** Share geometry once and pack the exact input/output mark pair in one primitive word.
 * Unlike the B-only interner, this directory also represents ordinary and genuine ZERO inputs.
 * FLOW output mark exclusions remain raw until actual-call application has finished. */
class StaticWriteKeyInterner(private val ap: ApManager) {
    private val geometryIds = HashMap<StaticWriteGeometry, Int>()
    private val geometries = ArrayList<StaticWriteGeometry>()
    private val labels = ArrayList<Long2IntOpenHashMap>()
    private val rowGeometry = IntArrayList()
    private val rowMarks = LongArrayList()

    @Synchronized fun intern(original: InitialAp, result: Pattern): Int {
        ap.cancellation.checkpoint()
        check(original.manager === ap) { "A static-write key must use its owner's AP manager" }
        check(result.fact.base == STATIC) { "A static-write key needs a static image" }
        check((original.mark is MarkSlot.Star) == (result.fact.mark is MarkSlot.Star)) {
            "A static-write key preserves the original's FLOW/TAINT relation"
        }
        fun geometry(pattern: Pattern): Pattern = pattern.copy(fact = pattern.fact.copy(
            path = Collections.unmodifiableList(ArrayList(pattern.fact.path)),
            mark = if (pattern.fact.mark is MarkSlot.Concrete) MarkSlot.STAR else pattern.fact.mark))
        val shape = StaticWriteGeometry(geometry(original.toPattern()), geometry(result))
        val shapeId = geometryIds.getOrPut(shape) {
            geometries.size.also {
                geometries += shape
                labels += Long2IntOpenHashMap().apply { defaultReturnValue(-1) }
            }
        }
        val input = original.mark
        val output = result.fact.mark
        val pair = if (input is MarkSlot.Concrete && output is MarkSlot.Concrete)
            ((input.mark.id.toLong() + 1L) shl 32) or ((output.mark.id.toLong() + 1L) and 0xffffffffL)
        else 0L
        val existing = labels[shapeId].get(pair)
        if (existing >= 0) return existing
        val id = rowGeometry.size
        rowGeometry.add(shapeId)
        rowMarks.add(pair)
        labels[shapeId].put(pair, id)
        return id
    }

    @Synchronized fun row(id: Int): StaticWriteKey {
        ap.cancellation.checkpoint()
        val shape = geometries[rowGeometry.getInt(id)]
        val pair = rowMarks.getLong(id)
        val original = if (pair == 0L) shape.original else shape.original.copy(fact = shape.original.fact.copy(
            mark = MarkSlot.Concrete(TaintMark((pair ushr 32).toInt() - 1))))
        val result = if (pair == 0L) shape.result else shape.result.copy(fact = shape.result.fact.copy(
            mark = MarkSlot.Concrete(TaintMark(pair.toInt() - 1))))
        return StaticWriteKey(ap.initial(original), result)
    }

    @Synchronized fun clear() {
        geometryIds.clear(); geometries.clear(); labels.clear(); rowGeometry.clear(); rowMarks.clear()
    }
}

/** Borrow only before the shared key directory is released at run-1 handoff. */
class FrozenStaticWrites internal constructor(
    val owner: MethodKey,
    val interner: StaticWriteKeyInterner,
    private val observed: IntArray,
    private val lost: IntArray,
    val peakCount: Int,
) {
    val observedCount: Int get() = observed.size
    val lostCount: Int get() = lost.size
    fun observedIds(): IntArray = observed.copyOf()
    fun lostIds(): IntArray = lost.copyOf()
    fun forEachObservedId(visit: (Int) -> Unit) { for (id in observed) visit(id) }
    fun forEachLostId(visit: (Int) -> Unit) { for (id in lost) visit(id) }
    fun observedRows(): Sequence<StaticWriteKey> = observed.asSequence().map(interner::row)
    fun lostRows(): Sequence<StaticWriteKey> = lost.asSequence().map(interner::row)
}

/** Actor-owned candidates, not a killed-only set. Keep every observed thin ID until the
 * joined final prune: FLOW-backed common storage can later erase a colored survivor. */
class KilledStaticWriteStore(
    private val owner: MethodKey,
    private val ap: ApManager,
    private val ops: ApOps,
    private val interner: StaticWriteKeyInterner,
) {
    private var candidates: IntLinkedOpenHashSet? = IntLinkedOpenHashSet()
    private var frozen: FrozenStaticWrites? = null
    val candidateCount: Int get() = frozen?.observedCount ?: checkNotNull(candidates).size
    var peakCount: Int = 0; private set

    fun observe(original: PremiseKey, result: Facts) {
        check(frozen == null) { "A completed static-write inventory cannot accept new observations" }
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(original, result)) return
        check(original is InitialAp) { "Run-1 static-write candidates have one original" }
        if (result.base != STATIC) return
        val pending = checkNotNull(candidates)
        for (leaf in ops.leaves(result)) {
            ap.cancellation.checkpoint()
            pending.add(interner.intern(original, leaf))
        }
        peakCount = maxOf(peakCount, pending.size)
    }

    /** Read current survivor views only at joined quiescence. Guidance normalization is
     * for equality here; observed rows retain their raw AP data for caller binding. */
    fun freeze(
        common: Sequence<Pair<PremiseKey, Facts>>,
        privateB: Sequence<StaticGuidanceEdge>,
    ): FrozenStaticWrites {
        frozen?.let { return it }
        val survivors = HashSet<StaticGuidanceEdge>()
        for ((original, result) in common) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.packet(original, result)) continue
            check(original is InitialAp) { "Run-1 summaries have one original" }
            if (result.base != STATIC) continue
            for (leaf in ops.leaves(result)) {
                ap.cancellation.checkpoint()
                val (from, to) = normalizeFlowSummaryPatterns(original.toPattern(), leaf)
                survivors += StaticGuidanceEdge.of(from, to)
            }
        }
        for (row in privateB) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.base(row.from.fact.base) || !RuntimeDataDomain.base(row.to.fact.base)) continue
            val (from, to) = normalizeFlowSummaryPatterns(row.from, row.to)
            survivors += StaticGuidanceEdge.of(from, to)
        }
        val observed = checkNotNull(candidates).toIntArray()
        val lost = IntArrayList()
        for (id in observed) {
            ap.cancellation.checkpoint()
            if (interner.row(id).guidance() !in survivors) lost.add(id)
        }
        return FrozenStaticWrites(owner, interner, observed, lost.toIntArray(), peakCount).also {
            frozen = it
            candidates = null // Release the mutable hash table, including its backing arrays.
        }
    }
}

AccessorInterner.kt.text:
package org.opentaint.dataflow.ap.ifds.access.util

import org.opentaint.dataflow.ap.ifds.Accessor
import org.opentaint.dataflow.ap.ifds.AnyAccessor
import org.opentaint.dataflow.ap.ifds.ClassStaticAccessor
import org.opentaint.dataflow.ap.ifds.ElementAccessor
import org.opentaint.dataflow.ap.ifds.FieldAccessor
import org.opentaint.dataflow.ap.ifds.FinalAccessor
import org.opentaint.dataflow.ap.ifds.TaintMarkAccessor
import org.opentaint.dataflow.ap.ifds.TypeInfoAccessor
import org.opentaint.dataflow.ap.ifds.TypeInfoGroupAccessor
import org.opentaint.dataflow.ap.ifds.ValueAccessor
import org.opentaint.dataflow.util.ConcurrentReadSafeObject2IntMap
import org.opentaint.dataflow.util.getOrCreateIndex
import org.opentaint.dataflow.util.object2IntMap

typealias AccessorIdx = Int

class AccessorInterner {
    private class AccessorStorage {
        private val indices = object2IntMap<Accessor>()
        private val accessors = ArrayList<Accessor>()

        fun index(accessor: Accessor): Int {
            val currentIndex = indices.getInt(accessor)
            if (currentIndex != ConcurrentReadSafeObject2IntMap.NO_VALUE) return currentIndex

            synchronized(this) {
                return indices.getOrCreateIndex(accessor) { newIdx ->
                    check(newIdx == accessors.size)
                    accessors.add(accessor)
                    return newIdx
                }
            }
        }

        fun getOrNull(idx: Int): Accessor? = accessors.getOrNull(idx)
    }

    private val fields = AccessorStorage()
    private val statics = AccessorStorage()
    private val taints = AccessorStorage()
    private val types = AccessorStorage()
    private val storageByBasicKind = arrayOf(fields, statics, taints)

    fun index(accessor: Accessor): AccessorIdx {
        val kind = when (accessor) {
            is FieldAccessor -> FIELD_KIND
            is ClassStaticAccessor -> STATIC_KIND
            is TaintMarkAccessor -> TAINT_KIND
            is TypeInfoAccessor -> TYPES_KIND
            is AnyAccessor -> return ANY_ACCESSOR_IDX
            is ElementAccessor -> return ELEMENT_ACCESSOR_IDX
            is FinalAccessor -> return FINAL_ACCESSOR_IDX
            is TypeInfoGroupAccessor -> return TYPE_INFO_GROUP_ACCESSOR_IDX
            is ValueAccessor -> return VALUE_ACCESSOR_IDX
        }

        if (kind.getAccessorBasicKind() != TYPES_OR_MARKER_KIND) {
            val storage = storageByBasicKind[kind]
            val idx = storage.index(accessor)
            return setAccessorKind(idx, kind, BASIC_KIND_BITS)
        } else {
            check(kind == TYPES_KIND)
            val idx = types.index(accessor)
            return setAccessorKind(idx, TYPES_KIND, TYPES_OR_MARKER_KIND_BITS)
        }
    }

    fun accessor(idx: AccessorIdx): Accessor? {
        val kind = idx.getAccessorBasicKind()
        if (kind != TYPES_OR_MARKER_KIND) {
            val storage = storageByBasicKind[kind]
            val accessorIdx = idx.getAccessorIdx(BASIC_KIND_BITS)
            return storage.getOrNull(accessorIdx)
        }

        val typesOrMarkerKind = idx.getAccessorKind(TYPES_OR_MARKER_KIND_MASK)
        if (typesOrMarkerKind == TYPES_KIND) {
            val accessorIdx = idx.getAccessorIdx(TYPES_OR_MARKER_KIND_BITS)
            return types.getOrNull(accessorIdx)
        }

        return when (idx) {
            FINAL_ACCESSOR_IDX -> FinalAccessor
            ELEMENT_ACCESSOR_IDX -> ElementAccessor
            VALUE_ACCESSOR_IDX -> ValueAccessor
            ANY_ACCESSOR_IDX -> AnyAccessor
            TYPE_INFO_GROUP_ACCESSOR_IDX -> TypeInfoGroupAccessor
            else -> error("Unexpected accessor $idx")
        }
    }

    companion object {
        const val BASIC_KIND_BITS = 2
        const val BASIC_KIND_MASK = 0b11
        const val FIELD_KIND = 0b00
        const val STATIC_KIND = 0b01
        const val TAINT_KIND = 0b10
        const val TYPES_OR_MARKER_KIND = 0b11

        const val TYPES_OR_MARKER_KIND_BITS = 1 + BASIC_KIND_BITS
        const val TYPES_OR_MARKER_KIND_MASK = (1 shl BASIC_KIND_BITS) or BASIC_KIND_MASK

        const val MARKERS_KIND = (0 shl BASIC_KIND_BITS) or TYPES_OR_MARKER_KIND
        const val TYPES_KIND = (1 shl BASIC_KIND_BITS) or TYPES_OR_MARKER_KIND

        const val FINAL_ACCESSOR_IDX = (0 shl TYPES_OR_MARKER_KIND_BITS) or MARKERS_KIND
        const val ELEMENT_ACCESSOR_IDX = (1 shl TYPES_OR_MARKER_KIND_BITS) or MARKERS_KIND
        const val VALUE_ACCESSOR_IDX = (2 shl TYPES_OR_MARKER_KIND_BITS) or MARKERS_KIND
        const val ANY_ACCESSOR_IDX = (3 shl TYPES_OR_MARKER_KIND_BITS) or MARKERS_KIND
        const val TYPE_INFO_GROUP_ACCESSOR_IDX = (4 shl TYPES_OR_MARKER_KIND_BITS) or MARKERS_KIND

        @Suppress("NOTHING_TO_INLINE")
        inline fun AccessorIdx.getAccessorBasicKind(): Int = getAccessorKind(BASIC_KIND_MASK)

        @Suppress("NOTHING_TO_INLINE")
        inline fun AccessorIdx.getAccessorKind(kindMask: Int): Int = this and kindMask

        @Suppress("NOTHING_TO_INLINE")
        inline fun AccessorIdx.getAccessorIdx(kindBits: Int): Int = this shr kindBits

        @Suppress("NOTHING_TO_INLINE")
        inline fun setAccessorKind(accessorIdx: Int, kind: Int, kindBits: Int): AccessorIdx =
            (accessorIdx shl kindBits) or kind

        fun AccessorIdx.isFieldAccessor(): Boolean = getAccessorBasicKind() == FIELD_KIND
        fun AccessorIdx.isStaticAccessor(): Boolean = getAccessorBasicKind() == STATIC_KIND
        fun AccessorIdx.isTaintMarkAccessor(): Boolean = getAccessorBasicKind() == TAINT_KIND
        fun AccessorIdx.isTypeInfoAccessor(): Boolean = getAccessorKind(TYPES_OR_MARKER_KIND_MASK) == TYPES_KIND

        fun AccessorIdx.isAlwaysUnrollNext(): Boolean =
            isTaintMarkAccessor()
                    || (this == FINAL_ACCESSOR_IDX)
                    || (this == VALUE_ACCESSOR_IDX)
                    || (this == TYPE_INFO_GROUP_ACCESSOR_IDX)
                    || isTypeInfoAccessor()
    }
}

