            else if(type.equals(AP+"PremiseSet"))names=List.of("data");
            else if(type.equals(AP+"Pattern"))names=List.of("fact","exclusion");
            else if(type.equals(AP+"PathFact"))names=List.of("base","path","tail","mark");
            else if(type.equals(AP+"Reach"))names=List.of("layer");
            else if(type.equals(AP+"FlowTree"))names=List.of("base","layer","exclusion","markExclusion","root","tail");
            else if(type.equals(AP+"TaintTree"))names=List.of("base","layer","root","exclusion","anyTail","nonSubsumable");
            else if(type.equals(AP+"TrieNode"))names=List.of("leaf","accessorData","childData","boundedDepth","size");
            else if(type.equals(AP+"TaintLeaves"))names=List.of("exact","any");
            else if(type.equals(AP+"MarkSet"))names=List.of("data");
            else if(type.equals(AP+"MarkExclusions"))names=List.of("atoms","fullAtoms");
            else if(type.equals(AP+"MarkSlot$Concrete"))names=List.of("mark");
            else if(type.equals(AP+"MarkSlot$Star"))names=List.of("excluded");
            else if(type.equals(AP+"ExclusionSet$Concrete"))names=List.of("data");
            else if(type.equals(AP+"ExclusionSet$Empty"))names=List.of();
            else if(type.equals("org.opentaint.dataflow.bidi.store.StaticWriteKey"))names=List.of("original","result");
            else if(type.equals(AP+"Layer")||type.equals(AP+"Tail")||type.equals(AP+"FlowLeaf")||type.equals(AP+"FullAtoms"))names=List.of("name");
