    static Map<String,Object> simple(ObjectReference object,String... names){Map<String,Object> result=map("type",object.referenceType().name(),"objectId",uid(object));for(String name:names)result.put(name,primitive(get(object,name)));return result;}
    static Map<String,Object> catalog(ObjectReference manager,Set<Integer> fields,Set<Integer> marks){
        ObjectReference accessors=obj(manager,"accessors"),table=obj(manager,"marks");List<Object> fieldRows=new ArrayList<>(),markRows=new ArrayList<>();
