    static Map<String,Value> locals(StackFrame frame)throws AbsentInformationException{return frame.getValues(frame.visibleVariables()).entrySet().stream().collect(LinkedHashMap::new,(m,e)->m.put(e.getKey().name(),e.getValue()),Map::putAll);}
