    static Map<String,Object> capture(BreakpointEvent event,String stage)throws Exception{
        ObjectReference binder=binder(event.thread()),writer=writer(event.thread()),manager=obj(obj(binder,"ops"),"manager");Map<String,Value> local=locals(event.thread().frame(0));
